"""Executed results only; keep automation, evidence, and reference truth distinct."""
import json
import xml.etree.ElementTree as ET

import pandas as pd

from common import CACHE,HERE,OUT


def report():
    load=lambda name:json.loads((OUT/name).read_text())
    files=load('file_evaluation_summary.json');pilot=load('pilot_pr_summary.json');main=load('main_pr_summary.json')
    usage=load('api_usage_report.json');comparison=load('comparison_summary.json');validation=load('validation_results.json');models=load('statistical_analysis_status.json')
    ps=pd.read_csv(OUT/'pilot_pr_outcomes.csv');ms=pd.read_csv(OUT/'main_pr_outcomes.csv');rates=pd.read_csv(OUT/'tables/rq1_testing_rates.csv')
    active=ms[ms.eligible_for_new_acquisition]
    changes=pd.read_csv(OUT/'tables/pr_detector_disagreements.csv')
    tests=ET.parse(OUT/'unit_tests.xml').getroot();n_tests=sum(int(x.attrib.get('tests',0)) for x in tests.iter('testsuite'))
    kinds={}
    for p in (CACHE/'github').glob('*.json'):
        r=json.loads(p.read_text());kind=r['request']['kind'];kinds[kind]=kinds.get(kind,0)+1
    headline=["# Content-based test detection: executed findings", "", "Updated November 16, 2026. Original data, midpoint baseline, historical pilot, caches, and human-review forms are preserved.", "",
        f"**Implemented and executed:** a static-content detector, prioritized added-file PR search with early exit, pinned GitHub retrieval/cache reuse, a resumable main-cohort queue, guarded Grok 4.3 integration, and coverage-aware RQ1 descriptions. All {validation['prior_files_hash_identical']} prior files remain hash-identical.", "",
        f"**Grok execution:** {usage['requests_attempted']} actual xAI request attempts; {usage['input_tokens']} input tokens; {usage['output_tokens']} output tokens; provider-reported cost **${usage['reported_cost_usd']:.2f}**. XAI_API_KEY was unavailable. No paid request was made. Live schema/model/account integration remains unvalidated; local SDK-parameter, schema, evidence, retry, and budget tests passed. Configure the key securely and run the at-most-ten-call smoke batch described in README.md.", "",
        "## Actual outcomes", "",
        "| Scope | PRs | Confirmed added test | Exhaustive negative | Unknown |", "|---|---:|---:|---:|---:|",
        f"| Historical pilot | {pilot['n_prs']} | {pilot['confirmed_added_tests']} | {pilot['confident_no_added_tests']} | {pilot['unknown']} |",
        f"| Entire main-cohort output queue | {main['n_prs']:,} | {main['confirmed_added_tests']} | {main['confident_no_added_tests']} | {main['unknown']:,} |", "",
        f"The main output includes the historical pilot plus a reproducible additional 24-PR acquisition subset, for {len(active)} active PRs total. It does not represent a completed content sweep of 3,186 PRs. All {main['confirmed_added_tests']} positive PR outcomes were confirmed by deterministic source analysis; Grok contributed zero classifications. Verification means pinned, hash-checked code plus classifier evidence, not independent human annotation, test execution, passing tests, or improved software quality.", "",
        f"The 56 cached-file evaluation produced **{files['deterministic_classes'].get('automated_test',0)} automated_test, {files['deterministic_classes'].get('test_support',0)} test_support, {files['deterministic_classes'].get('not_test',0)} not_test, and {files['deterministic_classes'].get('uncertain',0)} uncertain** results. It reused all existing content references without downloads. There were {files['determinate_disagreements']} resolved file-level disagreements with the filename detector: two Rust files with embedded tests missed by path rules and one Rust module file counted as a test by path rules despite declaring no cases itself. These are evidence-backed detector disagreements, not human-reference false-positive/false-negative rates. The 56 cases include modified/removed files and are not the added-file PR outcome sample.", "",
        "## Search efficiency and evidence", "",
        f"- Pilot: {pilot['total_files_inspected']} unique PR/file contents examined; mean {pilot['mean_files_inspected_per_pr']:.3f} and median {pilot['median_files_inspected_per_pr']:.1f} files per PR; {pilot['eligible_added_files']} eligible added-source files; {pilot['files_avoided_early_exit']} examinations avoided after positive early exits.",
        f"- Main: {main['total_files_inspected']} unique PR/file contents examined, including the pilot; {main['files_avoided_early_exit']} avoided after positive exits. Across the {len(active)} active PRs, mean {active.n_files_inspected.mean():.3f}, median {active.n_files_inspected.median():.1f}. Across all 3,186 queued PRs, the mean {main['mean_files_inspected_per_pr']:.4f} and median 0 reflect mostly uninspected PRs, not efficient negative verification.",
        f"- New GitHub reads: {sum(kinds.values())}, with request kinds {kinds}, below the configured 200-request total ceiling. Existing historical responses/content were reused. No full SpecMine download or repository clone sweep occurred.",
        "- Every positive records repository/PR, added-file path, full head SHA, Git blob SHA, SHA-256, evidence symbol/line, method, and inspected/eligible counts. Negatives require complete compatible file lists and a resolved negative/support decision for every eligible added file. Missing, truncated, unsupported, or ambiguous content remains unknown.", "",
        "Only added files are eligible for the primary outcome. Modified/removed examples remain in the separate file evaluation. Test directories are searched before test-like filenames, then other executable sources, including embedded tests. Existing repository files outside the net diff are never searched. Unknown cases do not prevent a later verified positive, and one positive cancels further retrieval for that PR.", "",
        "## What changed relative to the original detector", ""]
    for r in changes.itertuples():headline.append(f"- {r.repo_name} #{r.pr_number}: path result {int(r.test_added)} → content result {int(r.test_added_content_verified)}, supported by {r.confirmed_file_path}.")
    headline += ["",f"Among the {models['verified_n']} currently resolved main-cohort PRs, {len(changes)} disagree ({len(changes)/models['verified_n']:.1%}); both corrections are Rust and both negative-to-positive. The historical-head cohort has 37 resolved outcomes among its 39 PRs, with two disagreements. Neither comparison is an accuracy estimate. Remaining unknowns are exported by tool, repository, and language.", "",
        "## RQ1 reanalysis", "",
        "Recalculated rates are in outputs/tables/rq1_testing_rates.csv. Historical rows use independently retrieved historical-head feature labels; main-cohort rows use the original snapshot labels and are explicitly labeled as such. Paired path/content comparisons use the same resolved subset. The table reports unknown counts, Wilson reference intervals conditional on that selected subset, and conservative missingness identification bounds that permit every unknown to be either 0 or 1. The Wilson intervals do not correct sampling, verification selection, or repository clustering and are not population evidence.", "",
        "Historical-head descriptive rates (selected verified subset):", "",
        "| Feature | Absent: positives / verified | Present: positives / verified | Unknown absent / present |", "|---|---:|---:|---:|"]
    for feature,label in [('has_acceptance_criteria','Acceptance criteria'),('has_edge_cases','Edge cases')]:
        s=rates[rates.cohort.eq('verified_head_specifications_content_outcomes') & rates.tool.eq('all') & rates.feature.eq(feature)].set_index('feature_present')
        headline.append(f"| {label} | {int(s.loc[0,'test_added_content_positive'])}/{int(s.loc[0,'n_verified'])} | {int(s.loc[1,'test_added_content_positive'])}/{int(s.loc[1,'n_verified'])} | {int(s.loc[0,'n_unknown'])} / {int(s.loc[1,'n_unknown'])} |")
    headline += ["",f"Only {models['verified_n']}/3,186 main outcomes ({models['main_coverage']:.1%}) are resolved. Regression was withheld: {', '.join(models['reasons'])}. The historical pilot is small and was sampled on the old outcome; raw subset associations cannot be generalized. OpenSpec/Spec Kit exposure rates and missingness are exported separately. **The original RQ1 association conclusions cannot yet be replaced.** This extension establishes concrete measurement corrections, not a new positive/negative specification effect or a causal claim.", "",
        "![Verification coverage](outputs/figures/content_verification_coverage.png)", "",
        "## Remaining blockers and next steps before December 15", "",
        "The live Grok smoke batch requires XAI_API_KEY. Shell/PowerShell, parser-error, and other semantic cases remain queued; privacy-sensitive files may stay unresolved even with a key. One historical PR's live net diff differs from the frozen study and remains unknown. Most main-cohort PRs are unacquired; activate reproducible batches and use the request/cost estimates before larger acquisition. All unprocessed outcomes remain unknown.", "",
        "Run at most ten Grok attempts first, inspect the technical validation/accounting report, validate the smoke gate, then resume within the cumulative $3 cap. Broader execution needs enough repository/language/tool coverage to assess verification bias before fitting models. Independent human annotation of a separate stratified validation sample is still needed for accuracy, precision, or recall. It is not required to manually label every file to run the automated pipeline.", "",
        f"**Validation:** {n_tests} extension unit tests pass; evidence/completeness/budget checks pass; prior-work hashes pass. Retrieved source is never executed. SDK integration was exercised with test doubles only; those are not counted as xAI calls. Reproduction, secure key setup, all outputs, and limitations are documented in README.md.", ""]
    (HERE/'CONTENT_DETECTION_REPORT.md').write_text('\n'.join(headline),encoding='utf-8')
    brief=['# Content-based test detection: concise findings','',
        'Executed November 15–16, 2026. All work is isolated in content_test_detection/.', '',
        '**Implemented:** static Python AST and cross-language syntax-tree classification; prioritized added-file search with early exit; pinned GitHub/hash verification and cache reuse; resumable queues; Grok 4.3 (`none`) structured JSON integration with evidence checks, privacy filters, a cumulative $3 ceiling, and a ten-attempt smoke gate.', '',
        '**Actually executed:**', '',
        f'- Reclassified all 56 cached review files: {files["deterministic_classes"]["automated_test"]} automated tests, {files["deterministic_classes"]["test_support"]} support files, {files["deterministic_classes"]["not_test"]} non-tests, {files["deterministic_classes"]["uncertain"]} uncertain. No repeat downloads for these cases.',
        f'- Historical pilot: **{pilot["confirmed_added_tests"]} confirmed added-test PRs, {pilot["confident_no_added_tests"]} exhaustive negatives, {pilot["unknown"]} unknown**. Inspected {pilot["total_files_inspected"]} PR/file contents (mean {pilot["mean_files_inspected_per_pr"]:.3f}, median {pilot["median_files_inspected_per_pr"]:.1f}); avoided {pilot["files_avoided_early_exit"]} examinations through early stopping.',
        f'- Pilot plus 24 additional main-cohort PRs: **{main["confirmed_added_tests"]} confirmed added-test PRs, {main["confident_no_added_tests"]} exhaustive negatives**; all {main["unknown"]:,} other cohort rows remain unknown. Inspected {main["total_files_inspected"]} contents across these PRs, avoiding {main["files_avoided_early_exit"]} additional examinations. Counts include the pilot, so do not add the two rows together.',
        f'- {sum(kinds.values())} new GitHub reads under a 200-read cap; original datasets and all {validation["prior_files_hash_identical"]} prior project/pilot/review files remain hash-identical.',
        f'- **Grok calls: {usage["requests_attempted"]}; input/output tokens: {usage["input_tokens"]}/{usage["output_tokens"]}; actual reported API cost: ${usage["reported_cost_usd"]:.2f}.** XAI_API_KEY was missing. The live integration has not been validated; local SDK/test doubles are not counted as paid calls.',
        f'- {n_tests} extension tests and evidence/completeness/budget checks pass. Downloaded source code was never executed.', '',
        '**RQ1 findings:** Two Rust PRs previously labeled test-negative now have confirmed newly added files containing embedded tests. The resolved main subset disagrees with the old detector in 2/59 PRs. Historical and snapshot-feature rate tables are separate. Coverage is only 1.85% of the main cohort, so new regression estimates are withheld and the original association conclusions cannot yet be replaced. Detector comparisons are not human-reference accuracy, precision, or recall.', '',
        '**Before the December 15 submission:** securely configure XAI_API_KEY, run at most ten real calls, validate schema/evidence/accounting, then resume within the $3 ceiling. Resolve semantic/unsupported-language cases and extend repository/tool/language coverage through reproducible batches. Use independent reference annotation for a separate validation sample before reporting accuracy; the automated pipeline does not require manually labeling every file.', '',
        '[Full report](CONTENT_DETECTION_REPORT.md) · [Setup and reproduction](README.md) · [File results](outputs/file_classification_results.csv) · [PR outcomes](outputs/main_pr_outcomes.csv)', '']
    (HERE/'CONTENT_DETECTION_SUMMARY.md').write_text('\n'.join(brief),encoding='utf-8')
    return n_tests
